19 //! AXI Package
20 /// Contains all necessary type definitions, constants, and generally useful functions.
21 package axi_pkg;
22 
23   /// AXI Transaction Burst Width.
24   typedef logic [1:0]  burst_t;
25   /// AXI Transaction Response Type.
26   typedef logic [1:0]   resp_t;
27   /// AXI Transaction Cacheability Type.
28   typedef logic [3:0]  cache_t;
29   /// AXI Transaction Protection Type.
30   typedef logic [2:0]   prot_t;
31   /// AXI Transaction Quality of Service Type.
32   typedef logic [3:0]    qos_t;
33   /// AXI Transaction Region Type.
34   typedef logic [3:0] region_t;
35   /// AXI Transaction Length Type.
36   typedef logic [7:0]    len_t;
37   /// AXI Transaction Size Type.
38   typedef logic [2:0]   size_t;
39   /// AXI5 Atomic Operation Type.
40   typedef logic [5:0]   atop_t; // atomic operations
41   /// AXI5 Non-Secure Address Identifier.
42   typedef logic [3:0]  nsaid_t;
43 
44   /// AXI Transaction Burst Width.
45   parameter int unsigned BurstWidth  = $size(burst_t);
46   /// AXI Transaction Response Width.
47   parameter int unsigned RespWidth   = $size(resp_t);
48   /// AXI Transaction Cacheability Width.
49   parameter int unsigned CacheWidth  = $size(cache_t);
50   /// AXI Transaction Protection Width.
51   parameter int unsigned ProtWidth   = $size(prot_t);
52   /// AXI Transaction Quality of Service Width.
53   parameter int unsigned QosWidth    = $size(qos_t);
54   /// AXI Transaction Region Width.
55   parameter int unsigned RegionWidth = $size(region_t);
56   /// AXI Transaction Length Width.
57   parameter int unsigned LenWidth    = $size(len_t);
58   /// AXI Transaction Size Width.
59   parameter int unsigned SizeWidth   = $size(size_t);
60   /// AXI Lock Width.
61   parameter int unsigned LockWidth   = 32'd1;
62   /// AXI5 Atomic Operation Width.
63   parameter int unsigned AtopWidth   = $size(atop_t);
64   /// AXI5 Non-Secure Address Identifier.
65   parameter int unsigned NsaidWidth  = $size(nsaid_t);
66 
67   /// In a fixed burst:
68   /// - The address is the same for every transfer in the burst.
69   /// - The byte lanes that are valid are constant for all beats in the burst.  However, within
70   ///   those byte lanes, the actual bytes that have `wstrb` asserted can differ for each beat in
71   ///   the burst.
72   /// This burst type is used for repeated accesses to the same location such as when loading or
73   /// emptying a FIFO.
74   localparam BURST_FIXED = 2'b00;
